  test('Persona: Extra 1 - The Premium Glassmorphism Tester', async ({ page }) => {
    await page.mouse.click(640, 500);
    await page.waitForTimeout(1000);
    await page.mouse.click(640, 280);
    await page.waitForTimeout(1000);
    await page.mouse.click(640, 420);
    await page.keyboard.type("Glassy Business");
    await page.mouse.click(640, 500);
    await page.waitForTimeout(1000);
    expect(true).toBe(true);
  });

  test('Persona: Extra 2 - The CSS Inspector', async ({ page }) => {
    await page.goto('/login');
    const classes = await page.evaluate(() => document.querySelector('.glass').className);
    expect(classes).toContain('glass');
  });

